import { AsyncLocalStorage } from "node:async_hooks";
import { createPrivateWeakStore } from "../security/private-weak-store.js";
const storage = new AsyncLocalStorage();
const owners = createPrivateWeakStore();
/** Bind the callback to its privately held writer; these routing selectors confer no authority. */
export function bindToolCallAdmissionOwner(callback, owner) {
    if (owners.get(callback))
        throw new TypeError("Tool-call admission owner already bound");
    owners.set(callback, Object.freeze({ ...owner }));
}
export function getToolCallAdmissionOwner(callback) {
    return owners.get(callback);
}
/** Internal broker scope. Correlation fields in caller context never install a receipt. */
export async function runWithToolCallAdmissionReceipt(receipt, assertActive, operation, source) {
    assertActive();
    const scope = { active: true, receipt: Object.freeze({ ...receipt }), assertActive, source };
    try {
        return await storage.run(scope, operation);
    }
    finally {
        scope.active = false;
    }
}
export function getCurrentToolCallAdmissionReceipt() {
    const scope = storage.getStore();
    if (!scope?.active)
        return undefined;
    scope.assertActive();
    return scope.receipt;
}
/** Internal opaque callback identity, never a credential or caller-selected proof. */
export function getCurrentToolCallAdmissionSource() {
    const scope = storage.getStore();
    if (!scope?.active)
        return undefined;
    scope.assertActive();
    return scope.source;
}
